insert into players (name, pin, is_admin) values
  ('Simon', _random_pin(), true),
  ('Simmer', _random_pin(), false),
  ('Stefan', _random_pin(), false),
  ('Mario', _random_pin(), false),
  ('Sophie', _random_pin(), false),
  ('Lukas', _random_pin(), false),
  ('Caro', _random_pin(), false),
  ('DanKaho', _random_pin(), false),
  ('Andi', _random_pin(), false),
  ('Isabella', _random_pin(), false)
insert into missions (id, level, title, description) values
  (1, 1, 'Luft-Anstoßen', 'Bringe jemanden dazu, mit dir anzustoßen, ohne dass sich eure Gläser berühren.'),
  (2, 1, 'Schwache Hand', 'Bringe eine Person dazu, mit dir mit der schwachen Hand anzustoßen, weil du behauptest, das bringe beim Martiniloben Glück.'),
  (3, 1, 'Mineralisch', 'Nutze das Wort „mineralisch“ dreimal innerhalb von 2 Minuten im Gespräch mit derselben Person.'),
  (4, 1, 'Kostpass-Vergleich', 'Bringe jemanden dazu, dir seinen Martiniloben-Kostpass zu zeigen, um zu schauen, wer schon mehr Keller abgestempelt hat.'),
  (5, 1, 'Der Gansl-Köder', 'Behaupte beiläufig, Martinigansl sei eigentlich völlig überbewertet, und bringe jemanden dazu, das Gansl zu verteidigen.'),
  (6, 1, 'Servietten-Trick', 'Lass dir von jemandem eine Serviette reichen, ohne direkt danach zu fragen.'),
  (7, 1, 'Das Echo', 'Bringe jemanden dazu, das Wort „Abgang“ mindestens zweimal in einem Satz zu verwenden.'),
  (8, 1, 'Licht-Check', 'Bringe eine Person dazu, ihr Glas genau wie du gegen das Licht zu halten, um „die Farbe und Trübung“ zu prüfen.'),
  (9, 1, 'Augenkontakt', 'Stoße mit jemandem an und halte dabei ununterbrochen intensiven Augenkontakt, bis die Person lacht oder wegguckt.'),
  (10, 1, 'Leeres Glas', 'Schaffe es, dass jemand mit dir anstößt, obwohl sein oder dein Glas komplett leer ist.'),
  (11, 1, 'Kompliment-Falle', 'Entlocke jemandem ein Kompliment zu einem Kleidungsstück, das du schon ewig trägst.'),
  (12, 1, 'Der Witz', 'Bringe eine Person dazu, dir spontan einen Witz zu erzählen.'),
  (13, 1, 'Kaugummi-Schnorrer', 'Schaffe es, dass dir jemand unaufgefordert einen Kaugummi, ein Pfefferminz oder ein Taschentuch anbietet.'),
  (14, 1, 'Gläser-Träger', 'Bringe jemanden dazu, dein Weinglas für mindestens 30 Sekunden zu halten, während du angeblich „beide Hände für etwas brauchst“.'),
  (15, 1, 'Der Seewind', 'Überzeuge jemanden davon, dass der Wind am Neusiedlersee heute „eindeutig nach Salz“ riecht.'),
  (16, 1, 'Runden-Starter', 'Initiiere ein Anstoßen, bei dem mindestens 5 Leute aus eurer Gruppe gleichzeitig ihre Gläser heben.'),
  (17, 1, 'Wort-Schmuggel', 'Bringe eine Person dazu, das Wort „Schubkarre“ oder „Gummistiefel“ laut auszusprechen, indem du das Gespräch darauf lenkst.'),
  (18, 1, 'Leises Prost', 'Stoße mit jemandem an und flüstere den Trinkspruch so leise, dass die Person nachfragen muss, was du gesagt hast.'),
  (19, 1, 'Platzhalter', 'Bringe eine Person dazu, dir für 2 Minuten deinen Stehplatz oder Sitzplatz im Keller freizuhalten.'),
  (20, 1, 'Kleingeld-Suche', 'Bringe jemanden dazu, seine Hosentasche nach einer ganz bestimmten Münze (z. B. „Hast du genau 20 Cent?“) abzusuchen.'),
  (21, 1, 'Der Vorleser', 'Lass dir von jemandem vorlesen, was auf der Weinkarte oder Tafel eines Standes steht, direkt vor dem ihr steht.'),
  (22, 1, 'Too Slow', 'Bringe jemanden dazu, dir ein High-Five zu geben, und ziehe die Hand im letzten Moment weg.'),
  (23, 1, 'Kindheitsgeschichte', 'Bringe eine Person dazu, dir eine Anekdote aus ihrer Schulzeit zu erzählen.'),
  (24, 1, 'Snack-Teiler', 'Bringe jemanden dazu, dir freiwillig den letzten Bissen von seinem Schmalzbrot, Laugengebäck oder Snack anzubieten.'),
  (25, 1, 'Gegen-Anstoßen', 'Bringe jemanden dazu, beim Anstoßen mit dem Glasboden statt dem Glasrand anzustoßen.'),
  (26, 1, 'Fotograf', 'Bring eine Person dazu, dich zu bitten, ein Foto von ihr (oder ihr und jemand anderem) zu machen.'),
  (27, 1, 'Doppel-Prost', 'Bringe jemanden dazu, innerhalb von 60 Sekunden zweimal hintereinander mit dir anzustoßen.'),
  (28, 1, 'Jacken-Halter', 'Bringe jemanden dazu, deine Jacke, Mütze oder Tasche für mindestens 2 Minuten zu halten/tragen.'),
  (29, 1, 'Schnick-Schnack-Schnuck', 'Starte ohne Vorwarnung eine Runde Schnick-Schnack-Schnuck mit jemandem und bringe die Person dazu, mitzuspielen.'),
  (30, 1, 'Schluck-Angebot', 'Bringe jemanden dazu, dir ungefragt einen Schluck aus seinem Glas zum Probieren anzubieten.'),
  (31, 2, 'Der Feinschmecker', 'Erfinde beim Riechen am Glas eine absurde Note (z. B. „feuchter Schilfgürtel“, „alte Dachziegel“) und bringe jemanden dazu, zuzustimmen oder nachzuriechen.'),
  (32, 2, 'Korken-Schmuggel', 'Schmuggle unbemerkt einen Weinkorken in die Jacken-, Hosen- oder Handtasche eines Mitspielers, ohne dass es innerhalb von 2 Minuten auffällt.'),
  (33, 2, 'Podersdorf-Wahrzeichen', 'Organisiere ein Gruppenfoto mit mindestens 4 Leuten vor dem Podersdorfer Leuchtturm (oder an der Mole), ohne dass jemand Verdacht schöpft.'),
  (34, 2, 'Der Pseudo-Fakt', 'Überzeuge jemanden von einem völlig erfundenen Fakt über Podersdorf (z. B. „Der Leuchtturm wurde 1890 ursprünglich als Getreidesilo gebaut“).'),
  (35, 2, 'Foto-Fail', 'Bring jemanden dazu, für ein Foto zu posieren, mache aber stattdessen ein Video und lass die Person mindestens 5 Sekunden in Pose stehen.'),
  (36, 2, 'Absurder Trinkspruch', 'Bringe jemanden dazu, mit dir feierlich auf etwas völlig Belangloses anzustoßen (z. B. „auf den Erfinder des Schraubverschlusses“).'),
  (37, 2, 'Der Dieb', 'Lass unbemerkt einen kleinen Gegenstand eines Mitspielers mitgehen (z. B. Feuerzeug, Sonnenbrille) und behalte ihn 15 Minuten unentdeckt, bevor du ihn vorzeigst. (Nichts vom Winzer!)'),
  (38, 2, 'Identischer Wein', 'Lass dir von jemandem bestätigen, dass der aktuelle Wein „viel runder und besser“ schmeckt als der vorherige – obwohl es exakt derselbe Wein ist.'),
  (39, 2, 'Die Keller-Abkürzung', 'Überzeuge mindestens 3 Leute aus eurer Gruppe, dir zum nächsten Weinkeller zu folgen, obwohl du bewusst einen kleinen Umweg gehst.'),
  (40, 2, 'Kostpass-Sabotage', 'Bring jemanden dazu, dir seinen Kostpass zu geben, und kritzele unauffällig einen kleinen Punkt oder Smiley drauf.'),
  (41, 2, 'Leeres Glas riechen', 'Bringe eine Person dazu, an einem komplett leeren Weinglas zu riechen, um „die Restsüße der Hefe“ zu beurteilen.'),
  (42, 2, 'Der Spiegel', 'Verwickle jemanden in ein Gespräch und spiegle jede seiner Handbewegungen für 1 Minute unauffällig, bis die Person stutzt.'),
  (43, 2, 'Tannin-Experte', 'Bezeichne einen völlig normalen Weißwein als „erstaunlich tanninreich“ und bringe jemanden dazu, dir zuzustimmen.'),
  (44, 2, 'Guck mal da!', 'Schaue plötzlich erschrocken in den Himmel oder auf den Boden und bringe mindestens zwei Leute dazu, dorthin zu schauen, wo nichts ist.'),
  (45, 2, 'Ohrwurm-Pflanzer', 'Summe eine bekannte Melodie so lange beiläufig vor dich hin, bis jemand aus eurer Gruppe das Lied laut mitsingt oder pfeift.'),
  (46, 2, 'Tisch-Klopfer', 'Überzeuge jemanden davon, dass es beim Martiniloben Brauch ist, nach dem Anstoßen einmal kurz mit dem Glas auf den Tisch zu klopfen.'),
  (47, 2, 'Rebsorten-Vortrag', 'Bring eine Person dazu, dir mindestens 1 Minute lang ernsthaft den Unterschied zwischen zwei Rebsorten zu erklären.'),
  (48, 2, 'Der Schulter-Korken', 'Platziere einen leichten Gegenstand (Korken, Bierdeckel) auf der Kapuze oder Schulter eines Mitspielers, sodass er dort 1 Minute bleibt.'),
  (49, 2, 'Das erfundene Sprichwort', 'Baue ein frei erfundenes Sprichwort in ein Gespräch ein (z. B. „Wie der Winzer sät, so bricht der Rebstock“) und bringe jemanden dazu, zu nicken.'),
  (50, 2, 'Fremdsprachen-Prost', 'Bring eine Person dazu, einen Trinkspruch in einer komplett erfundenen oder ihr fremden Sprache nachzusprechen.'),
  (51, 2, 'Schwenk-Meister', 'Schwenke dein Weinglas demonstrativ so lange und intensiv im Kreis, bis dich jemand darauf anspricht.'),
  (52, 2, 'Finger-Test', 'Überzeuge jemanden davon, vor dem ersten Schluck eines neuen Weins kurz mit dem kleinen Finger den Glasrand zu befeuchten.'),
  (53, 2, 'Essens-Berater', 'Überrede jemanden an einem Essensstand oder im Gasthaus dazu, etwas zu bestellen, das er/sie ursprünglich gar nicht nehmen wollte.'),
  (54, 2, 'Puls-Fühler', 'Bringe jemanden dazu, dir am Handgelenk den Puls zu fühlen oder deine Handfläche zu lesen.'),
  (55, 2, 'Unter-dem-Arm-Prost', 'Bringe eine Person dazu, beim Anstoßen die Arme miteinander zu verhaken (Brüderschaft-Style), obwohl ihr euch schon ewig kennt.'),
  (56, 2, 'Schraubverschluss-Debatte', 'Starte eine ernste Diskussion über Korken vs. Schraubverschluss und bringe jemanden dazu, leidenschaftlich Partei für eine Seite zu ergreifen.'),
  (57, 2, 'Bananen-Note', 'Behaupte, dein Wein rieche „eindeutig nach Gummibärchen oder Banane“, und bringe jemanden dazu, an deinem Glas zu riechen.'),
  (58, 2, 'Der Stuhl-Tausch', 'Bringe eine Person dazu, dir ihren Sitzplatz oder den besten Stehplatz am Fass freiwillig zu überlassen.'),
  (59, 2, 'Gläser-Rückgabe', 'Bringe jemanden dazu, deine leeren Gläser für dich mit zum Stand zurückzubringen.'),
  (60, 2, 'Boden-Opfer', 'Bringe jemanden dazu, nach dem Anstoßen feierlich einen winzigen Tropfen Wein auf den Boden zu schütten („für den heiligen Martin“).'),
  (61, 3, 'Disco-Maus (Martinskeller-Edition)', 'Im Martinskeller musst du den DJ dazu bringen, den Song „Barbie Girl“ von Aqua zu spielen – und mindestens 3 Leute aus eurer Gruppe müssen dazu aktiv auf der Tanzfläche mitsingen oder tanzen.'),
  (62, 3, 'Der Glas-Tausch', 'Tausche dein Weinglas unbemerkt gegen das Glas eines Mitspielers aus. Die Mission gilt erst als geschafft, wenn der Mitspieler einen Schluck aus deinem vertauschten Glas trinkt, ohne es zu checken (danach wird natürlich wieder zurückgetauscht).'),
  (63, 3, 'Sommelier-Bluff beim Winzer', 'Verwickle einen Winzer in einem Weinkeller in ein Gespräch und stelle einen deiner Mitspieler als „Weinkritiker aus Wien“ vor – schaffe es, dass der Winzer dem Freund mindestens einen besonderen Tropfen extra einschenkt.'),
  (64, 3, 'Gruppen-Synchron', 'Bringe mindestens 5 Leute aus eurer Gruppe dazu, gleichzeitig für mindestens 10 Sekunden auf einem Bein zu stehen, ohne dass jemand weiß, dass es deine Mission ist.'),
  (65, 3, 'Das Geständnis', 'Entlocke einem Mitspieler im Gespräch ein echtes, peinliches Kindheits- oder Jugendgeheimnis, das mindestens zwei andere aus der Runde bestätigen noch nicht gekannt zu haben.'),
  (66, 3, 'Fremd-Jubiläum', 'Bringe mindestens 3 komplett fremde Weinfest-Besucher dazu, gemeinsam mit dir und zwei Freunden lautstark auf „10 Jahre Podersdorfer Synchronschwimm-Verein“ anzustoßen.'),
  (67, 3, 'Der Taschendieb-Reverse', 'Schmuggle einen Löffel oder Bierdeckel unbemerkt in die Jacken- oder Handtasche eines Mitspielers und sorge dafür, dass die Person ihn erst mindestens 15 Minuten später selbst entdeckt.'),
  (68, 3, 'Blindverkostungs-Bluff', 'Verbinde einem Mitspieler die Augen (oder lass sie schließen), gib ihm zweimal exakt denselben Wein zu kosten und überzeuge ihn davon, dass der zweite Schluck ein „deutlich teurerer Barrique-Reserve“ ist.'),
  (69, 3, 'Der Zeitlupen-Moment', 'Führe ein Gespräch mit einem Mitspieler an einem Stehtisch und bewege deine Hände und deinen Kopf für volle 60 Sekunden in extrem langsamer Zeitlupe, ohne als Mission enttarnt zu werden.'),
  (70, 3, 'Die Macarena-Falle', 'Starte im Martinskeller oder an einem Musik-Stand den Macarena-Tanz und bringe mindestens 4 Leute aus eurer Gruppe dazu, die Choreografie komplett mitzutanzen.'),
  (71, 3, 'Gratis-Geburtstagsstamperl', 'Überzeuge einen Winzer oder Ausschank-Mitarbeiter davon, dass ein Mitspieler heute Geburtstag hat, sodass diese Person ein Gratis-Stamperl oder ein Ständchen vom Standpersonal bekommt.'),
  (72, 3, 'Der Kellner-Trick', 'Nimm einem Mitspieler mitten im Gespräch völlig selbstverständlich und kommentarlos das halbvolle Weinglas aus der Hand, stelle es zwei Meter weiter auf einen Tisch und gehe weg, ohne dass er dich innerhalb von 15 Sekunden darauf anspricht.'),
  (73, 3, 'Dreifacher Korken-Schmuggel', 'Platziere im Laufe des Wochenendes bei drei verschiedenen Mitspielern jeweils unbemerkt einen Weinkorken in der Jackentasche oder Kapuze, sodass er dort mindestens 5 Minuten unentdeckt bleibt.'),
  (74, 3, 'Neusiedlersee-Taufe', 'Bringe einen Mitspieler dazu, freiwillig die bloße Hand bis zum Handgelenk in den kalten Neusiedlersee zu tauchen (Beweisfoto nötig!).'),
  (75, 3, 'Der Dialekt-Durchhalter', 'Sprich mit einem Mitspieler für volle 3 Minuten durchgehend in strengem Tirolerisch oder Vorarlbergerisch, ohne dass die Person dich als „Mission!“ enttarnt.'),
  (76, 3, 'Stehtisch-Choreografie', 'Bringe mindestens 4 Leute gleichzeitig am Stehtisch dazu, genau wie du die Arme zu verschränken und das rechte Bein über das linke zu schlagen.'),
  (77, 3, 'Der dreiste Snack-Raub', 'Nimm im Gespräch ganz ruhig drei Bissen hintereinander vom Teller oder aus der Snacktüte eines Mitspielers, während du ihm ununterbrochen tief in die Augen schaust – ohne ein Wort darüber zu verlieren.'),
  (78, 3, 'Das Mikrofon-Trio', 'Organisiere ein Foto von dir, einem Winzer und mindestens drei Freunden, auf dem alle ihr Weinglas wie ein Gesangsmikrofon vor den Mund halten.'),
  (79, 3, 'Der Hagel-Alarm', 'Überzeuge mindestens 3 Leute aus eurer Gruppe davon, dass laut Regenradar in 5 Minuten ein kurzer Hagelschauer über Podersdorf zieht, sodass alle ihre Kapuzen aufsetzen oder sich unterstellen.'),
  (80, 3, 'Komplimente-Domino', 'Bringe Person A dazu, Person B ein Kompliment zu machen, und sorge durch geschickte Gesprächsführung dafür, dass Person B innerhalb von 2 Minuten Person C ein Kompliment macht.'),
  (81, 3, 'Die Fantasie-Bestellung', 'Bringe einen Mitspieler dazu, am Ausschank ernsthaft nach einem „2024er Podersdorfer Schilf-Cuvée“ zu fragen (ein Wein, der gar nicht existiert).'),
  (82, 3, 'Der perfekte Schatten', 'Folge einem Mitspieler beim Wechsel von einem Weinkeller zum nächsten für volle 2 Minuten im exakten Gleichschritt direkt hinterher, ohne dass die Person dich umdreht und erwischt.'),
  (83, 3, 'Ein-Wort-Trinkspruch', 'Initiiere einen Gruppen-Trinkspruch, bei dem alle 10 Spieler reihum jeweils genau ein einziges Wort sagen müssen, bis ein grammatikalisch korrekter Satz entsteht.'),
  (84, 3, 'Der Kostpass-Tausch', 'Tausche deinen eigenen Martiniloben-Kostpass unbemerkt gegen den Kostpass eines Mitspielers aus und lasse mindestens einen Keller auf dem fremden Pass abstempeln, bevor es auffällt.'),
  (85, 3, 'Stille-Post-Gerücht', 'Setze bei einem Mitspieler das Gerücht in die Welt, dass ein bestimmter anderer Freund „vorhin seinen Kostpass im letzten Keller liegen gelassen hat“ – und schau zu, wie der erste den zweiten darauf anspricht.'),
  (86, 3, 'Der 15-Sekunden-Freeze', 'Friere mitten in einer Unterhaltung an einem Stehtisch für volle 15 Sekunden komplett wie eine Statue ein (ohne zu blinzeln) und rede danach weiter, als wäre nichts geschehen.'),
  (87, 3, 'Korken-Turm', 'Baue auf einem Tisch einen Turm aus mindestens 5 Weinkorken oder Bierdeckeln und bringe zwei verschiedene Mitspieler dazu, unaufgefordert jeweils mindestens ein weiteres Teil hinzuzufügen.'),
  (88, 3, 'Polonaise im Keller', 'Starte in einem Weinkeller oder im Martinskeller eine Polonaise und bringe mindestens 3 völlig fremde Weinfest-Besucher dazu, sich hinten anzuhängen.'),
  (89, 3, 'Die Alibi-Bestätigung', 'Verwickle einen Mitspieler in ein Gespräch mit einem Winzer und bringe den Freund dazu, eine völlig erfundene Geschichte von dir (z. B. „Wir sind heute schon 15 Kilometer um den See gejoggt“) ernsthaft zu bestätigen.'),
  (90, 3, 'Der Pechvogel-Toast', 'Bringe am Sonntag mindestens 6 Leute aus eurer Gruppe dazu, sich im Kreis aufzustellen und feierlich auf den größten Pechvogel des Wochenendes anzustoßen.')
